"""Generate or verify the ZIP fixtures used by install_archive_tests.rs."""

import argparse
from io import BytesIO
from pathlib import Path
from zipfile import ZIP_DEFLATED, ZIP_STORED, ZipFile, ZipInfo


FIXTURE_DIR = Path(__file__).parent
# These are the DOS timestamps recorded in the original stdlib-generated files.
VALID_TIME = (2026, 10, 17, 13, 11, 58)
UNSAFE_TIME = (2026, 10, 17, 13, 45, 38)
CORRUPT_TIME = (2026, 10, 17, 13, 11, 24)
TRUNCATED_TIME = (2026, 10, 17, 13, 11, 24)


def zip_bytes(entries):
    stream = BytesIO()
    with ZipFile(stream, "w") as archive:
        for info, content in entries:
            archive.writestr(info, content)
    return stream.getvalue()


def info(name, timestamp, compression=ZIP_STORED, mode=None, dos_attributes=0):
    entry = ZipInfo(name, date_time=timestamp)
    entry.compress_type = compression
    if mode is not None:
        entry.external_attr = (mode << 16) | dos_attributes
    return entry


def valid_zip(include_empty_directory=True, timestamp=VALID_TIME):
    entries = [
        (
            info("chrome-linux64/", timestamp, mode=0o40775, dos_attributes=0x10),
            b"",
        ),
        (
            info(
                "chrome-linux64/nested/",
                timestamp,
                mode=0o40775,
                dos_attributes=0x10,
            ),
            b"",
        ),
    ]
    if include_empty_directory:
        entries.append(
            (
                info(
                    "chrome-linux64/empty/",
                    VALID_TIME,
                    mode=0o40775,
                    dos_attributes=0x10,
                ),
                b"",
            )
        )

    entries.extend(
        [
            (
                info(
                    "chrome-linux64/nested/chrome",
                    (1980, 1, 1, 0, 0, 0),
                    ZIP_DEFLATED,
                    0o100755,
                ),
                b"#!/bin/sh\necho chrome\n",
            ),
            (
                info(
                    "chrome-linux64/nested/privileged",
                    (1980, 1, 1, 0, 0, 0),
                    ZIP_DEFLATED,
                    0o104755,
                ),
                b"privileged bits must be removed",
            ),
            (
                info(
                    "chrome-linux64/nested/data.txt", timestamp, ZIP_DEFLATED
                ),
                "deflated payload",
            ),
        ]
    )
    return zip_bytes(entries)


def unsafe_paths_zip():
    entries = [
        (info("../outside.txt", UNSAFE_TIME, ZIP_DEFLATED), b"outside"),
        (
            info(
                "chrome-linux64/../../../outside.txt", UNSAFE_TIME, ZIP_DEFLATED
            ),
            b"outside",
        ),
        (
            info("chrome-linux64/../escape.txt", UNSAFE_TIME, ZIP_DEFLATED),
            b"inside",
        ),
    ]
    return zip_bytes(entries)


def corrupt_crc_zip():
    archive = bytearray(
        zip_bytes(
            [
                (
                    info("chrome-linux64/corrupt.txt", CORRUPT_TIME),
                    b"CRC must fail",
                )
            ]
        )
    )
    name_length = int.from_bytes(archive[26:28], "little")
    extra_length = int.from_bytes(archive[28:30], "little")
    data_start = 30 + name_length + extra_length
    archive[data_start] ^= 0x01
    return bytes(archive)


def fixtures():
    original_valid = valid_zip(
        include_empty_directory=False, timestamp=TRUNCATED_TIME
    )
    return {
        "installer-valid.zip": valid_zip(),
        "installer-unsafe-paths.zip": unsafe_paths_zip(),
        "installer-corrupt-crc.zip": corrupt_crc_zip(),
        "installer-truncated.zip": original_valid[: len(original_valid) // 2],
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument(
        "--check",
        action="store_true",
        help="compare generated bytes with fixtures without writing (default)",
    )
    mode.add_argument("--write", action="store_true", help="rewrite fixture files")
    args = parser.parse_args()

    mismatches = []
    for filename, generated in fixtures().items():
        path = FIXTURE_DIR / filename
        if args.write:
            path.write_bytes(generated)
            print(f"wrote {filename}")
        elif not path.exists() or path.read_bytes() != generated:
            mismatches.append(filename)
        else:
            print(f"verified {filename}")

    if mismatches:
        parser.exit(1, f"fixture bytes differ: {', '.join(mismatches)}\n")


if __name__ == "__main__":
    main()
